/**
 * Noto Sans Devanagari font faces (Regular + Bold) embedded as base64.
 *
 * The server has no system fonts, so the receipt PDF renderer registers
 * these font files directly. Base64 keeps them inside the module graph,
 * so the Vercel function bundler includes them automatically.
 */
export const NOTO_SANS_DEVANAGARI_REGULAR_BASE64 = ``;

export const NOTO_SANS_DEVANAGARI_BOLD_BASE64 = ``;
